class Solution {
public:
    int minFlips(int a, int b, int c) {
        int flips = 0;
        while (a || b || c) {
            int x = a & 1, y = b & 1, z = c & 1;
            if (z == 0) flips += x + y;
            else if (x == 0 && y == 0) flips += 1;
            a >>= 1;
            b >>= 1;
            c >>= 1;
        }
        return flips;
    }
};
